lid OAuth token'=>'Неверный токен OAuth','Hey, congrats! Everything looks good on PublishPress Pro\'s Slack settings.'=>'Привет, поздравляю! Всё выглядит хорошо в настройках Slack для PublishPress Pro.','Error from Slack: '=>'Ошибка от Slack: ','Error from PublshPress.com: '=>'Ошибка от PublshPress.com: ']];